// The preflight of the seed and the three permissions `up` gains (DEVDESK-505,
// NX-02a, step 5). Against the scripted kubectl of preflight_test.go, which
// records every "auth can-i" question in order.
//
// Choices of the tests, to settle with the code:
//   - OpSeed is appended after OpStatus; no earlier value moves.
//   - The questions of seed, in this order, all in the bench namespace:
//     get deployments, list pods, get pods, get services, create
//     pods/portforward, patch deployments/scale. The port-forward to
//     svc/bench-upstream reads the Service, then the pod, before it POSTs to
//     pods/portforward (get services, get pods, create pods/portforward);
//     patch deployments/scale is EnsureUpstream's.
//   - up keeps its fourteen questions where they are (they already hold get pods)
//     and asks the three new ones after them, in this order: patch
//     deployments/scale (EnsureUpstream), create pods/portforward and get
//     services (the port-forward the seed opens). The order among the three is
//     the tests' choice; the fourteen first ones do not move.
//   - seed refuses an absent or a foreign namespace, like provision and status,
//     and does not read the Services of the cluster (that is up's NodePort
//     check); it reads the node address like provision.
//   - A refused question ends the preflight there: the later ones are not asked.
//   - Nothing is ever written.

// asked renders the can-i questions the fake saw: "verb resource", plus "-n <ns>"
// or "-A" when the question was scoped.
func asked(f *fakeKubectl) []string {
	out := make([]string, 0, len(f.asked))
	for _, q := range f.asked {
		s := q.verb + " " + q.resource
		switch {
		case q.allNamespaces:
			s += " -A"
		case q.namespace != "":
			s += " -n " + q.namespace
		}
		out = append(out, s)
	}
	return out
}

func inNamespace(p Params, questions ...string) []string {
	out := make([]string, 0, len(questions))
	for _, q := range questions {
		out = append(out, q+" -n "+p.Namespace)
	}
	return out
}

