func TestListComponentsStopsOnATokenThatNeverEnds(t *testing.T) {
	b := provisioned(t)
	b.nexus.AddComponents(dockerProxyRepository, comps("a", "b")...)
	b.nexus.SetComponentPageSize(2)
	b.nexus.LoopComponentToken(dockerProxyRepository)
	c := b.adminClient()
	before := len(b.nexus.Requests())

	got, err := b.list(c, dockerProxyRepository)
	if err == nil {
		t.Fatalf("listComponents = %+v, want an error for a listing that never ends", got)
	}
	if calls := len(b.requestsFrom(before)); calls > maxComponentRequests {
		t.Errorf("%d calls before giving up, want at most %d", calls, maxComponentRequests)
	}
}

